55: func (m *KubernetesSecretsManager) isRefreshNeeded(secret *corev1.Secret) bool {
56: 	log := logrus.WithFields(logrus.Fields{"secret.namespace": secret.Namespace, "secret.name": secret.Name})
57: 	expiryBaseline := time.Now().Add(secretExpiryDelta)
58: 	expiryStr, ok := secret.Annotations[metadata.TLSSecretSVIDExpiryAnnotation]
59: 	if !ok {
60: 		log.Warn("secret missing expiry annotation, will re-create it")
61: 		return true
62: 	}
63: 
64: 	log = log.WithField("expiry", expiryStr)
65: 
66: 	expiry, err := time.Parse(time.RFC3339, expiryStr)
67: 	if err != nil {
68: 		log.WithError(err).Error("failed parsing secret expiry time, will re-create it")
69: 		return true
70: 	}
71: 
72: 	if expiry.Before(expiryBaseline) {
73: 		log.Info("secret expiry is near, will re-create it")
74: 		return true
75: 	}
76: 
77: 	log.Debug("secret expiry is far enough")
78: 	return false
79: }
